"use client";
import React,{useState} from "react";import Link from "next/link";import {useRouter} from "next/navigation";import api from "@/lib/api";
import {useResource,Notice,field,button,message} from "@/components/BillingUI";
interface Router{id:number;name:string}interface Plan{id:number;name:string;price:number;sessionTimeout:number}
interface Host{address?:string;"mac-address"?:string;"host-name"?:string}
export default function Page(){const nav=useRouter();const routers=useResource<Router>("/api/routers");const plans=useResource<Plan>("/api/packages");const [router,setRouter]=useState("");const [name,setName]=useState("");const [plan,setPlan]=useState("");const [mac,setMac]=useState("");const [address,setAddress]=useState("");const [expires,setExpires]=useState("");const [paid,setPaid]=useState(false);const [amount,setAmount]=useState("");const [method,setMethod]=useState("CASH");const [reference,setReference]=useState("");const [hosts,setHosts]=useState<Host[]>([]);const [seen,setSeen]=useState("");const [note,setNote]=useState("");const [saving,setSaving]=useState(false);
 const loadHosts=async(id:string)=>{setHosts([]);setSeen("");if(!id)return;try{const res=await api.get<{hosts:Host[];seenAt:string}>(`/api/routers/${id}/hosts`);setHosts(res.data.hosts);setSeen(res.data.seenAt);}catch(e){setNote(message(e));}};
 const save=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);try{await api.post("/api/bindings",{routerId:Number(router),name,packageId:plan?Number(plan):null,mac,address:address||null,expiresAt:expires?new Date(expires).toISOString():null,recordPayment:paid,amount:paid?Number(amount):null,method:paid?method:null,reference:reference||null});nav.push("/dashboard/bindings");}catch(e){setNote(message(e));}finally{setSaving(false);}};
 return <div className="mx-auto max-w-5xl space-y-6"><Link href="/dashboard/bindings" className="text-xs text-slate-500">IP bindings / Create</Link><h1 className="text-2xl font-semibold text-slate-900">Bind a device</h1><Notice text={note||routers.error||plans.error}/><form onSubmit={save} className="space-y-6"><div className="grid gap-5 rounded-xl border border-slate-200 bg-white p-6 sm:grid-cols-2"><label className="text-xs text-slate-700 sm:col-span-2">MikroTik *<select required value={router} onChange={e=>{setRouter(e.target.value);void loadHosts(e.target.value);}} className={field}><option value="">Select router</option>{routers.data.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label className="text-xs text-slate-700">Name *<input required maxLength={120} value={name} onChange={e=>setName(e.target.value)} className={field}/></label><label className="text-xs text-slate-700">Package<select required={paid} value={plan} onChange={e=>{setPlan(e.target.value);const p=plans.data.find(p=>p.id===Number(e.target.value));if(p)setAmount(String(p.price));}} className={field}><option value="">Free / internal bypass</option>{plans.data.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><small className="mt-2 block text-slate-500">Sets speed and default expiry from now.</small></label><div><label className="text-xs text-slate-700">Active host<select aria-label="Active host" defaultValue="" onChange={e=>{const h=hosts[Number(e.target.value)];if(h){setMac(h["mac-address"]||"");setAddress(h.address||"");}}} className={field}><option value="">Select a reported DHCP lease</option>{hosts.map((h,i)=><option key={i} value={i}>{h.address} · {h["mac-address"]} {h["host-name"]}</option>)}</select></label><button type="button" disabled={!router} onClick={()=>loadHosts(router)} className="mt-2 text-xs text-blue-700">Refresh reported hosts</button><p className="mt-1 text-xs text-slate-500">{seen?`Last report: ${new Date(seen).toLocaleString()}`:"No host report yet. Enter the IP and MAC manually."}</p></div><label className="text-xs text-slate-700">Address<input required={!!plan} value={address} onChange={e=>setAddress(e.target.value)} placeholder="10.10.0.7" className={field}/><small className="mt-2 block text-slate-500">Optional for free MAC-only bypass. Required when a package sets speed limits.</small></label><label className="text-xs text-slate-700">MAC address *<input required pattern="[0-9A-Fa-f]{2}(:[0-9A-Fa-f]{2}){5}" value={mac} onChange={e=>setMac(e.target.value.toUpperCase())} placeholder="AA:BB:CC:DD:EE:FF" className={field}/></label><label className="text-xs text-slate-700">Expires at<input type="datetime-local" value={expires} onChange={e=>setExpires(e.target.value)} className={field}/><small className="mt-2 block text-slate-500">Overrides package expiry. Without a package or date, access never expires.</small></label></div>
 <section className="space-y-5 rounded-xl border border-slate-200 bg-white p-6"><h2 className="text-sm font-semibold text-slate-900">Payment recording</h2><label className="flex gap-3 text-sm text-slate-700"><input type="checkbox" checked={paid} onChange={e=>setPaid(e.target.checked)}/>Record payment</label><p className="text-xs text-slate-500">Records an already received payment in revenue. Leave off for free or internal access.</p>{paid&&<div className="grid gap-5 sm:grid-cols-2"><label className="text-xs text-slate-700">Amount paid (UGX) *<input required type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} className={field}/></label><label className="text-xs text-slate-700">Payment method *<select value={method} onChange={e=>setMethod(e.target.value)} className={field}>{["CASH","MTN","AIRTEL","BANK","OTHER"].map(m=><option key={m}>{m}</option>)}</select></label><label className="text-xs text-slate-700 sm:col-span-2">Payment reference<input maxLength={128} value={reference} onChange={e=>setReference(e.target.value)} className={field}/></label></div>}</section><div className="flex gap-4"><button disabled={saving} className={button}>{saving?"Saving…":"Create binding"}</button><Link href="/dashboard/bindings" className="py-2 text-xs text-slate-500">Cancel</Link></div></form></div>;
}
